from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
with tempfile.TemporaryDirectory(prefix='cfs-month-columns-') as tmp:
 fixture=Path(tmp)/'data.json';seed=json.loads(subprocess.check_output(['node','-e','process.stdout.write(JSON.stringify(require("./scripts/fixture").seed()))'],cwd=ROOT));epic_id=next(iter(seed['remote']));aug='August 2026 Update:\nEarly readiness review completed.\n\n';seed['remote'][epic_id]['comments']=aug+seed['remote'][epic_id]['comments'];seed['docs']['epic:'+epic_id]['comments']=seed['remote'][epic_id]['comments'];fixture.write_text(json.dumps(seed))
 server=subprocess.Popen(['node','server.js','--fixture'],cwd=ROOT,env={**os.environ,'PORT':'8397','CFS_FIXTURE_FILE':str(fixture)},stdout=subprocess.PIPE,text=True)
 try:
  assert 'Release Review:' in server.stdout.readline()
  with sync_playwright() as p:
   browser=p.chromium.launch();page=browser.new_page(viewport={'width':1440,'height':1000});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:8397');expect(page.locator('#epic-count')).to_have_text('6');page.locator('#review-month').fill('2026-11');page.locator('#review-month').dispatch_event('change');expect(page.locator('.month-head')).to_have_count(3)
   page.locator('#columns-button').click();expect(page.locator('#month-col-2026-08')).not_to_be_checked();page.locator('#month-col-2026-08').check();page.locator('#save-columns').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('.month-head')).to_have_count(4);page.reload();expect(page.locator('#epic-count')).to_have_text('6');expect(page.locator('.month-head')).to_have_count(4);page.locator('#columns-button').click();page.locator('#month-col-2026-08').uncheck();expect(page.locator('#month-col-2026-11')).to_be_enabled();page.locator('#month-col-2026-11').uncheck();page.locator('#month-col-2026-09').uncheck();assert page.locator('#col-months').evaluate('(e)=>e.indeterminate');page.locator('#save-columns').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('.month-head')).to_have_count(1);expect(page.locator('.month-head')).to_contain_text('Oct 2026');expect(page.locator('[data-do="month"][data-month="2026-11"]')).to_have_count(0)
   page.reload();expect(page.locator('#epic-count')).to_have_text('6');expect(page.locator('.month-head')).to_have_count(1);page.locator('#columns-button').click();expect(page.locator('#month-col-2026-11')).not_to_be_checked();expect(page.locator('#month-col-2026-10')).to_be_checked();page.locator('#col-months').check();page.locator('#col-months').uncheck();page.locator('#save-columns').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('.month-head')).to_have_count(0);expect(page.locator('.month-cell')).to_have_count(0);page.reload();expect(page.locator('#epic-count')).to_have_text('6');expect(page.locator('.month-head')).to_have_count(0)
   page.locator('#columns-button').click();page.locator('#col-months').check();page.locator('#save-columns').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('.month-head')).to_have_count(4);page.locator('#columns-button').click();page.locator('#month-col-2026-08').uncheck();page.locator('#save-columns').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('.month-head')).to_have_count(3);page.locator('#add-month').click();expect(page.locator('#new-month')).to_have_value('2026-08');page.locator('#save-month').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('.month-head')).to_have_count(4);expect(page.locator('#review-month')).to_have_value('2026-11');assert json.loads(fixture.read_text())['remote']==seed['remote'];assert not errors,errors;browser.close();print('Month column checks passed: hide individual/review/all months, reload persistence, restore all; GUS comments unchanged.')
 finally:server.terminate();server.wait(timeout=10)
